WIDTH, HEIGHT = 85.6343, 19.8322


def draw_coates(pdf, x, y, width):
    """Draw the supplied mark at its original aspect ratio, anchored at bottom left."""
    art = Drawing(WIDTH, HEIGHT)
    art.add(SvgPath(OUTLINE, fillColor=HexColor("#F36C21"), strokeColor=None))
    pdf.saveState()
    pdf.translate(x, y)
    pdf.scale(width / WIDTH, width / WIDTH)
    renderPDF.draw(art, pdf, 0, 0)
    pdf.restoreState()
